const appts = $("📋 Get Tomorrow Appointments").all();
const weather = $("🌦️ Get Weather Forecast").first().json;
let weatherScore = 0;
try {
  const forecast = weather.list ? weather.list[0] : {};
  const temp = forecast.main?.temp || 70;
  const condition = forecast.weather?.[0]?.main || "Clear";
  if (["Rain","Snow","Thunderstorm"].includes(condition)) weatherScore = 25;
  else if (condition === "Clouds" && temp < 40) weatherScore = 15;
  else weatherScore = 0;
} catch(e) { weatherScore = 5; }

const results = [];
for (const item of appts) {
  const a = item.json;
  if (!a.patient_id) continue;
  const pastNoShows = parseInt(a.no_show_count) || 0;
  const totalAppts = parseInt(a.total_appointments) || 1;
  const historyScore = Math.min(40, (pastNoShows / totalAppts) * 100);
  const dayOfWeek = new Date(a.date).getDay();
  const dayScore = (dayOfWeek === 1) ? 15 : (dayOfWeek === 5) ? 10 : 5;
  const distanceMiles = parseFloat(a.distance_miles) || 5;
  const distScore = distanceMiles > 20 ? 20 : distanceMiles > 10 ? 12 : 5;
  const totalRisk = Math.min(100, Math.round(historyScore + weatherScore + dayScore + distScore));
  const riskLevel = totalRisk >= 70 ? "HIGH" : totalRisk >= 40 ? "MEDIUM" : "LOW";
  results.push({ json: { ...a, risk_score: totalRisk, risk_level: riskLevel, risk_breakdown: { history: Math.round(historyScore), weather: weatherScore, day: dayScore, distance: distScore }}});
}
return results.length ? results : [{ json: { skip: true }}];

